using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RemainingSurvey {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("Remaining_Domes_Art");Physics.SyncTransforms();var models=new List<object>();foreach(string kind in new[]{"Props","Environment"})foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/"+kind+"/B5"),"RD_*.fbx")){string path="Assets/Afrer_Seconds/05.Model/"+kind+"/B5/"+Path.GetFileName(f);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var g=AssetDatabase.LoadAssetAtPath<GameObject>(path);var meshes=g.GetComponentsInChildren<MeshFilter>();var b=meshes[0].sharedMesh.bounds;foreach(var m in meshes.Skip(1))b.Encapsulate(m.sharedMesh.bounds);models.Add(new{name=Path.GetFileNameWithoutExtension(f),center=V(b.center),size=V(b.size)});}
 var overlaps=new List<object>();var cols=group.GetComponentsInChildren<Collider>().Where(c=>c.enabled&&!c.isTrigger).ToArray();for(int i=0;i<cols.Length;i++)for(int j=i+1;j<cols.Length;j++){var a=cols[i];var b=cols[j];if(!a.bounds.Intersects(b.bounds))continue;Vector3 dir;float depth;if(Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out dir,out depth)&&depth>.015f)overlaps.Add(new{a=a.transform.parent.name+"/"+a.name,b=b.transform.parent.name+"/"+b.name,depth});}
 var result=new{models,overlaps,lights=root.GetComponentsInChildren<Light>(true).Length,player=UnityEngine.Object.FindFirstObjectByType<CharacterController>()?.height};File.WriteAllText(Repo+"/SourceAssets/B5_RemainingDomes/survey.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{models=models.Count,overlaps,lights=result.lights,player=result.player};}
}
